// runtime threshold is predictable.
func SyntheticCalibrationSet() []CalibrationEdge {
	set := make([]CalibrationEdge, 0, 24)
	for i := 0; i < 9; i++ {
		set = append(set, CalibrationEdge{EdgeType: "CALLS", VerbalConfidence: 0.95, CorrectlyPredicted: true})
