	set = append(set, CalibrationEdge{EdgeType: "CALLS", VerbalConfidence: 0.95, CorrectlyPredicted: false})
	for i := 0; i < 6; i++ {
		set = append(set, CalibrationEdge{EdgeType: "DATA_FLOWS", VerbalConfidence: 0.6, CorrectlyPredicted: i%2 == 0})
