// applyDatabricksCalibration runs §12's optional I-CALM / Conformal Risk
// Control / AI-Search chain (#47-#56) when the config opts in. It is off by
// default: with both flags false this is a no-op and the pipeline behaves
// exactly as before. With the flags on but no DATABRICKS_HOST /
// DATABRICKS_TOKEN in the environment, the chain still runs but every call
// fails closed via UnavailableDatabricksClient, leaving the schema's
// Databricks-reserved fields null — the mandatory coverage baseline (#35)
// never depends on any of this.
func applyDatabricksCalibration(ctx context.Context, config fidelity.Config, reconciliation *fidelity.Reconciliation) error {
	if !config.Databricks.CalibrationEnabled && !config.Databricks.CoverageCorroborationEnabled {
		return nil
	}
	client := fidelity.DatabricksClientFromEnv(config)
	if config.Databricks.CalibrationEnabled {
		if config.Databricks.Gate.Mode != "icalm_crc" {
			return fmt.Errorf("databricks.calibration_enabled requires gate.mode: icalm_crc (the fallback logistic-regression tier, §12.7, is not built in this release)")
		}
		threshold, err := fidelity.RuntimeThreshold(config)
		if err != nil {
			return fmt.Errorf("databricks calibration: %w", err)
		}
		fidelity.CalibrateAdvisoryEdges(ctx, reconciliation, client, threshold)
	}
	if config.Databricks.CoverageCorroborationEnabled {
		fidelity.CorroborateUnverifiableCoverage(ctx, reconciliation, client)
	}
	return nil
}

