func TestVerifyIntentWiresDatabricksCalibrationFailingClosedWithoutCreds(t *testing.T) {
	// calibration_enabled with no DATABRICKS_HOST/TOKEN in the environment:
	// the chain runs but every call fails closed, so the pipeline still
	// succeeds and the JSON contract is unchanged.
	t.Setenv("DATABRICKS_HOST", "")
	t.Setenv("DATABRICKS_TOKEN", "")
	repo := t.TempDir()
	if err := os.WriteFile(filepath.Join(repo, "fidelity.config.yaml"), []byte(calibrationOn), 0o600); err != nil {
		t.Fatal(err)
	}
	var output, errOutput bytes.Buffer
	err := runVerifyIntentWithAdapter(t.Context(), Options{Env: EntireEnv{RepoRoot: repo}, Stdout: &output, Stderr: &errOutput}, []string{"checkpoint-1", "--base", "checkpoint-0"}, testFidelityAdapter{})
	if err != nil {
		t.Fatal(err)
	}
	var response verifyIntentResponse
	if err := json.Unmarshal(output.Bytes(), &response); err != nil {
		t.Fatalf("stdout was not clean JSON: %v\n%s", err, output.String())
	}
	for _, entry := range response.Verification.Reconciliation.AdvisoryLowConfidence {
		if entry.VerbalConfidence != nil || entry.ConformalGatePassed != nil {
			t.Fatalf("no-credential run must leave Databricks fields null: %#v", entry)
