	for _, stage := range []Stage{StageCapture, StageDeclare, StageObserve, StageReconcile, StageManifest} {
		if err := runner.RunStage(ctx, stage, request); err != nil {
			return fmt.Errorf("Fidelity %s stage: %w", stage, err)
		}
	}
	return nil
}

