package fidelity

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

// corpus.go is the AI Search index ingestion pipeline's repo-side half (#51):
// it turns a checkout into a set of natural-language documents — the repo's
// own commit messages, source comments/docstrings, and Markdown — that the
// corroboration step (§12.4, §12.15) queries. Extraction is pure and
// no-network so it is built and tested here; databricks.go's SyncCorpus
// pushes the same []CorpusDoc into a Delta table + Vector Search index, and
// LocalIndex below serves the identical query contract with no Databricks at
// all, which is what makes corroboration demonstrable end-to-end today.

// CorpusDoc is one indexable document. Kind is "commit", "comment", or "doc"
// (a whole Markdown/plain-text file). ID is stable across runs so a re-sync
// updates rather than duplicates: "commit:<sha>" or "<path>:<startline>".
type CorpusDoc struct {
	ID      string `json:"id"`
	Kind    string `json:"kind"`
	Path    string `json:"path"`
	Content string `json:"content"`
}

// corpusMaxCommits and corpusMaxFileBytes keep a large repo's ingestion
// bounded — the same posture as the graph provider's own file-size skips.
const (
	corpusMaxCommits   = 2000
	corpusMaxFileBytes = 512 * 1024
)

var corpusSkipDir = map[string]bool{
	".git": true, "node_modules": true, "vendor": true, "dist": true,
	"build": true, ".entire": true, ".codex": true, "testdata": true,
}

// lineCommentPrefix / blockComment map an extension to its comment syntax.
// A file with no entry contributes no comment docs (its Markdown, if any, is
// picked up as a whole-file "doc" instead).
var lineCommentPrefix = map[string][]string{
	".go": {"//"}, ".js": {"//"}, ".jsx": {"//"}, ".ts": {"//"}, ".tsx": {"//"},
	".java": {"//"}, ".c": {"//"}, ".h": {"//"}, ".cc": {"//"}, ".cpp": {"//"},
	".rs": {"//"}, ".swift": {"//"}, ".kt": {"//"}, ".scala": {"//"}, ".dart": {"//"},
	".py": {"#"}, ".rb": {"#"}, ".sh": {"#"}, ".bash": {"#"}, ".yaml": {"#"},
	".yml": {"#"}, ".toml": {"#"}, ".pl": {"#"}, ".r": {"#"},
}

var wholeFileDocExt = map[string]bool{".md": true, ".mdx": true, ".markdown": true, ".txt": true, ".rst": true}

var wordCharRE = regexp.MustCompile(`[A-Za-z0-9_]`)

// BuildCorpus walks repo and returns its corroboration corpus. It shells out
// to git for commit messages (data passed as separate args, never a shell
// string) and reads working-tree files for comments and Markdown.
func BuildCorpus(ctx context.Context, repo string) ([]CorpusDoc, error) {
	if strings.TrimSpace(repo) == "" {
		return nil, fmt.Errorf("BuildCorpus requires a repository path")
	}
	docs := make([]CorpusDoc, 0, 512)

	commitDocs, err := commitMessageDocs(ctx, repo)
	if err != nil {
		return nil, err
	}
	docs = append(docs, commitDocs...)

	walkErr := filepath.WalkDir(repo, func(path string, entry os.DirEntry, err error) error {
		if err != nil {
			return nil // an unreadable entry is skipped, not fatal — best-effort ingestion
		}
		if entry.IsDir() {
			if corpusSkipDir[entry.Name()] {
				return filepath.SkipDir
			}
			return nil
		}
		info, err := entry.Info()
		if err != nil || info.Size() == 0 || info.Size() > corpusMaxFileBytes {
			return nil
		}
		rel, err := filepath.Rel(repo, path)
		if err != nil {
			return nil
		}
		rel = filepath.ToSlash(rel)
		ext := strings.ToLower(filepath.Ext(path))
		switch {
		case wholeFileDocExt[ext]:
			content, err := os.ReadFile(path)
			if err != nil || !hasProse(string(content)) {
				return nil
			}
			docs = append(docs, CorpusDoc{ID: rel + ":1", Kind: "doc", Path: rel, Content: normalizeWhitespace(string(content))})
		case len(lineCommentPrefix[ext]) > 0:
			docs = append(docs, commentDocs(path, rel, lineCommentPrefix[ext])...)
		}
		return nil
	})
	if walkErr != nil {
		return nil, fmt.Errorf("walk repository for corpus: %w", walkErr)
	}
	return docs, nil
}

func commitMessageDocs(ctx context.Context, repo string) ([]CorpusDoc, error) {
	command := exec.CommandContext(ctx, "git", "-C", repo, "log",
		fmt.Sprintf("--max-count=%d", corpusMaxCommits), "--no-merges", "--format=%H%x00%B%x1e")
	out, err := command.Output()
	if err != nil {
		// A repo with no commits yet, or git missing, is not fatal for
		// ingestion — comments and Markdown still make a usable corpus.
		return nil, nil
	}
	var docs []CorpusDoc
	for _, record := range strings.Split(string(out), "\x1e") {
		record = strings.Trim(record, "\n")
		if record == "" {
			continue
		}
		sha, message, found := strings.Cut(record, "\x00")
		if !found || !hasProse(message) {
			continue
		}
		docs = append(docs, CorpusDoc{
			ID: "commit:" + strings.TrimSpace(sha), Kind: "commit", Path: "",
			Content: normalizeWhitespace(message),
		})
	}
	return docs, nil
}

// commentDocs groups consecutive comment lines into one document each, so a
// doc comment above a function is retrieved as a unit rather than line by
// line. Shebangs and single-token directive lines (nolint, eslint-…) are
// dropped as noise.
func commentDocs(path, rel string, prefixes []string) []CorpusDoc {
	file, err := os.Open(path)
	if err != nil {
		return nil
	}
	defer file.Close()

	var docs []CorpusDoc
	var block []string
	blockStart := 0
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	lineNumber := 0
	flush := func() {
		defer func() { block = nil }()
		if len(block) == 0 {
			return
		}
		text := normalizeWhitespace(strings.Join(block, " "))
		if !hasProse(text) || isDirectiveNoise(text) {
			return
		}
		docs = append(docs, CorpusDoc{
			ID: fmt.Sprintf("%s:%d", rel, blockStart), Kind: "comment", Path: rel, Content: text,
		})
	}
	for scanner.Scan() {
		lineNumber++
		trimmed := strings.TrimSpace(scanner.Text())
		comment, ok := stripCommentPrefix(trimmed, prefixes)
		if !ok {
			flush()
			continue
		}
		if len(block) == 0 {
			blockStart = lineNumber
		}
		block = append(block, comment)
	}
	flush()
	return docs
}

func stripCommentPrefix(line string, prefixes []string) (string, bool) {
	for _, prefix := range prefixes {
		if strings.HasPrefix(line, prefix) {
			body := strings.TrimSpace(strings.TrimPrefix(line, prefix))
			if strings.HasPrefix(body, "!") { // shebang written as "#!"
				return "", false
			}
			return body, true
		}
	}
	return "", false
}

var directiveNoiseRE = regexp.MustCompile(`^(nolint|noqa|eslint-|prettier-|type:|go:generate|go:build|\+build|cgo |region|endregion|pragma|@ts-|istanbul )`)

func isDirectiveNoise(text string) bool {
	return directiveNoiseRE.MatchString(strings.ToLower(strings.TrimSpace(text)))
}

func hasProse(text string) bool {
	return len(wordCharRE.FindAllString(text, 4)) >= 4
}

var whitespaceRE = regexp.MustCompile(`\s+`)

func normalizeWhitespace(text string) string {
	return strings.TrimSpace(whitespaceRE.ReplaceAllString(text, " "))
}

// WriteCorpusJSONL writes docs as one JSON object per line — the local
// artifact fidelity-index produces, the input LocalIndex reads back, and the
// exact row shape SyncCorpus uploads to the Delta source table.
func WriteCorpusJSONL(path string, docs []CorpusDoc) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create corpus directory: %w", err)
	}
	file, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("create corpus file: %w", err)
	}
	defer file.Close()
	writer := bufio.NewWriter(file)
	encoder := json.NewEncoder(writer)
	encoder.SetEscapeHTML(false)
	for _, doc := range docs {
		if err := encoder.Encode(doc); err != nil {
			return fmt.Errorf("encode corpus row: %w", err)
		}
	}
	return writer.Flush()
}

// LoadCorpusJSONL reads a file written by WriteCorpusJSONL.
func LoadCorpusJSONL(path string) ([]CorpusDoc, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	var docs []CorpusDoc
	scanner := bufio.NewScanner(file)
	scanner.Buffer(make([]byte, 0, 64*1024), 4*1024*1024)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		var doc CorpusDoc
		if err := json.Unmarshal([]byte(line), &doc); err != nil {
			return nil, fmt.Errorf("parse corpus row: %w", err)
		}
		docs = append(docs, doc)
	}
	return docs, scanner.Err()
}

// LocalIndex is a BM25 retriever over a CorpusDoc set. It implements the same
// query contract as Databricks AI Search hybrid retrieval (databricks.go's
// Corroborate), so CalibrateAdvisoryEdges / CorroborateUnverifiableCoverage
// run unchanged against it with no workspace, no quota risk, and no network —
// this is the §20.2 local fallback, reached only because the hosted index has
// no populated Delta table yet (see BUILDATHON.md).
type LocalIndex struct {
	docs        []CorpusDoc
	docTokens   [][]string
	docFreq     map[string]int
	avgDocLen   float64
	scoreFloor  float64
	snippetSpan int
}

var tokenRE = regexp.MustCompile(`[a-z0-9_]{2,}`)

func tokenize(text string) []string {
	return tokenRE.FindAllString(strings.ToLower(text), -1)
}

// NewLocalIndex builds the retriever. An empty corpus yields an index whose
// Corroborate always returns (false, "", nil) — "attempted, no evidence",
// exactly the empty-hosted-index behavior CalibrateAdvisoryEdges expects.
func NewLocalIndex(docs []CorpusDoc) *LocalIndex {
	index := &LocalIndex{
		docs: docs, docFreq: make(map[string]int),
		scoreFloor: 1.0, snippetSpan: 260,
	}
	var totalLen int
	for _, doc := range docs {
		tokens := tokenize(doc.Content)
		index.docTokens = append(index.docTokens, tokens)
		totalLen += len(tokens)
		seen := make(map[string]bool, len(tokens))
		for _, token := range tokens {
			if !seen[token] {
				seen[token] = true
				index.docFreq[token]++
			}
		}
	}
	if len(docs) > 0 {
		index.avgDocLen = float64(totalLen) / float64(len(docs))
	}
	return index
}

const (
	bm25K1 = 1.5
	bm25B  = 0.75
)

// Corroborate scores hypothesis against every document and returns the best
// hit above the score floor. Signature matches DatabricksClient.Corroborate.
func (index *LocalIndex) Corroborate(_ context.Context, hypothesis string) (bool, string, error) {
	queryTokens := tokenize(hypothesis)
	if len(queryTokens) == 0 || len(index.docs) == 0 {
		return false, "", nil
	}
	total := float64(len(index.docs))
	bestScore, bestDoc := 0.0, -1
	for docIndex, tokens := range index.docTokens {
		if len(tokens) == 0 {
			continue
		}
		termCount := make(map[string]int, len(tokens))
		for _, token := range tokens {
			termCount[token]++
		}
		var score float64
		docLen := float64(len(tokens))
		for _, queryToken := range queryTokens {
			frequency := float64(termCount[queryToken])
			if frequency == 0 {
				continue
			}
			df := float64(index.docFreq[queryToken])
			idf := math.Log(1 + (total-df+0.5)/(df+0.5))
			norm := frequency * (bm25K1 + 1) / (frequency + bm25K1*(1-bm25B+bm25B*docLen/index.avgDocLen))
			score += idf * norm
		}
		if score > bestScore {
			bestScore, bestDoc = score, docIndex
		}
	}
	if bestDoc < 0 || bestScore < index.scoreFloor {
		return false, "", nil
	}
	return true, index.snippet(index.docs[bestDoc]), nil
}

// ScoreEdge fails closed: a local corpus can corroborate a hypothesis but
// cannot produce an I-CALM verbal confidence. CalibrateAdvisoryEdges already
// treats this error as "leave verbal_confidence null", so an advisory edge
// with only a local index still reaches corroboration.
func (index *LocalIndex) ScoreEdge(context.Context, string, []string) (float64, error) {
	return 0, fmt.Errorf("local corpus index does not score edges (no I-CALM model); corroboration only")
}

func (index *LocalIndex) snippet(doc CorpusDoc) string {
	prefix := ""
	if doc.Path != "" {
		prefix = doc.Path + ": "
	} else if strings.HasPrefix(doc.ID, "commit:") {
		prefix = doc.ID + ": "
	}
	body := doc.Content
	if len(body) > index.snippetSpan {
		body = body[:index.snippetSpan] + "…"
	}
	return prefix + body
}

// CorpusSummary is fidelity-index's machine-readable result.
type CorpusSummary struct {
	Documents  int            `json:"documents"`
	ByKind     map[string]int `json:"by_kind"`
	OutputPath string         `json:"output_path"`
	Pushed     bool           `json:"pushed_to_databricks"`
	PushDetail string         `json:"push_detail,omitempty"`
}

func SummarizeCorpus(docs []CorpusDoc, outputPath string) CorpusSummary {
	byKind := map[string]int{}
	for _, doc := range docs {
		byKind[doc.Kind]++
	}
	kinds := make([]string, 0, len(byKind))
	for kind := range byKind {
		kinds = append(kinds, kind)
	}
	sort.Strings(kinds)
	return CorpusSummary{Documents: len(docs), ByKind: byKind, OutputPath: outputPath}
}

