// DatabricksClientFromEnv picks the corroboration/scoring backend for
// verify-intent, in priority order:
//
//  1. DatabricksHTTPClient — when DATABRICKS_HOST and DATABRICKS_TOKEN are
//     both set. Serving endpoint from DATABRICKS_SERVING_ENDPOINT; vector
//     search index from DATABRICKS_VECTOR_SEARCH_INDEX or config's
//     databricks.ai_search.index_name. Credentials are never read from
//     committed config.
//  2. LocalIndex — when there are no HTTP credentials but corpusPath (the
//     fidelity-index artifact) exists. BM25 over the repo's own corpus:
//     real corroboration, no workspace, no quota risk.
//  3. UnavailableDatabricksClient — nothing configured. Every field stays
//     null, exactly as the schema promises when Databricks is off.
//
// A misconfigured environment degrades down this list rather than erroring
// the run: the mandatory coverage baseline (#35) never depends on any of it.
func DatabricksClientFromEnv(config Config, corpusPath string) DatabricksClient {
	endpoint := os.Getenv("DATABRICKS_SERVING_ENDPOINT")
	if endpoint == "" {
		endpoint = "databricks-meta-llama-3-1-8b-instruct"
	}
	index := config.Databricks.AISearch.IndexName
	if env := os.Getenv("DATABRICKS_VECTOR_SEARCH_INDEX"); env != "" {
		index = env
	}
	if client, err := NewDatabricksHTTPClientFromEnv(endpoint, index); err == nil {
		return client
	}
	if corpusPath != "" {
		if docs, err := LoadCorpusJSONL(corpusPath); err == nil && len(docs) > 0 {
			return NewLocalIndex(docs)
		}
	}
	return UnavailableDatabricksClient{}
}

// UCTargetsFromEnv is the Unity Catalog plumbing SyncCorpus needs. All five
// come from the environment — they name workspace resources, not secrets,
// but keeping them out of committed config matches the credential posture.
type UCTargets struct {
	Catalog          string // DATABRICKS_UC_CATALOG
	Schema           string // DATABRICKS_UC_SCHEMA
	Volume           string // DATABRICKS_UC_VOLUME (a UC Volume for the raw NDJSON)
	WarehouseID      string // DATABRICKS_SQL_WAREHOUSE_ID (runs the CREATE TABLE)
	EmbeddingEndpoint string // DATABRICKS_EMBEDDING_ENDPOINT (e.g. "databricks-gte-large-en")
}

func UCTargetsFromEnv() (UCTargets, error) {
	targets := UCTargets{
		Catalog: os.Getenv("DATABRICKS_UC_CATALOG"), Schema: os.Getenv("DATABRICKS_UC_SCHEMA"),
		Volume: os.Getenv("DATABRICKS_UC_VOLUME"), WarehouseID: os.Getenv("DATABRICKS_SQL_WAREHOUSE_ID"),
		EmbeddingEndpoint: os.Getenv("DATABRICKS_EMBEDDING_ENDPOINT"),
	}
	var missing []string
	for name, value := range map[string]string{
		"DATABRICKS_UC_CATALOG": targets.Catalog, "DATABRICKS_UC_SCHEMA": targets.Schema,
		"DATABRICKS_UC_VOLUME": targets.Volume, "DATABRICKS_SQL_WAREHOUSE_ID": targets.WarehouseID,
		"DATABRICKS_EMBEDDING_ENDPOINT": targets.EmbeddingEndpoint,
	} {
		if strings.TrimSpace(value) == "" {
			missing = append(missing, name)
		}
	}
	if len(missing) > 0 {
		return UCTargets{}, fmt.Errorf("SyncCorpus needs %s set", strings.Join(missing, ", "))
	}
	return targets, nil
}

// SyncCorpus is the hosted half of the ingestion pipeline (#51): upload the
// corpus NDJSON to a UC Volume, (re)create a Change-Data-Feed Delta table
// over it via the SQL Statement Execution API, then create-or-sync a
// DELTA_SYNC Vector Search index with a managed embedding column. The
// resulting index name is what Corroborate queries.
//
// ponytail: the individual REST calls are each minimal and shape-correct,
// but the full create→sync sequence was NOT run against a live workspace in
// this session (no SQL warehouse / embedding endpoint were provisioned) —
// see BUILDATHON.md. The local path (NewLocalIndex) is the verified
// end-to-end route; this is the drop-in for when the workspace resources
// exist. Run `fidelity-index --push` to exercise it.
func (client DatabricksHTTPClient) SyncCorpus(ctx context.Context, docs []CorpusDoc) (string, error) {
	targets, err := UCTargetsFromEnv()
	if err != nil {
		return "", err
	}
	var ndjson bytes.Buffer
	encoder := json.NewEncoder(&ndjson)
	encoder.SetEscapeHTML(false)
	for _, doc := range docs {
		if err := encoder.Encode(doc); err != nil {
			return "", fmt.Errorf("encode corpus row: %w", err)
		}
	}

	volumePath := fmt.Sprintf("/Volumes/%s/%s/%s/fidelity-corpus.ndjson", targets.Catalog, targets.Schema, targets.Volume)
	if err := client.putFile(ctx, volumePath, ndjson.Bytes()); err != nil {
		return "", fmt.Errorf("upload corpus to %s: %w", volumePath, err)
	}

	table := fmt.Sprintf("%s.%s.fidelity_corpus", targets.Catalog, targets.Schema)
	statements := []string{
		fmt.Sprintf("CREATE OR REPLACE TABLE %s AS SELECT id, kind, path, content FROM read_files('%s', format => 'json')", table, volumePath),
		fmt.Sprintf("ALTER TABLE %s SET TBLPROPERTIES (delta.enableChangeDataFeed = true)", table),
	}
	for _, statement := range statements {
		if err := client.runSQL(ctx, targets.WarehouseID, statement); err != nil {
			return "", fmt.Errorf("run %q: %w", statement, err)
		}
	}

	indexName := fmt.Sprintf("%s.%s.fidelity_corpus_index", targets.Catalog, targets.Schema)
	if err := client.ensureVectorIndex(ctx, indexName, table, targets.EmbeddingEndpoint); err != nil {
		return "", err
	}
	return indexName, nil
}

func (client DatabricksHTTPClient) putFile(ctx context.Context, volumePath string, body []byte) error {
	url := client.Host + "/api/2.0/fs/files" + volumePath + "?overwrite=true"
	request, err := http.NewRequestWithContext(ctx, http.MethodPut, url, bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("build upload request: %w", err)
	}
	request.Header.Set("Authorization", "Bearer "+client.Token)
	request.Header.Set("Content-Type", "application/octet-stream")
	response, err := client.HTTP.Do(request)
	if err != nil {
		return fmt.Errorf("upload request failed: %w", err)
	}
	defer response.Body.Close()
	if response.StatusCode != http.StatusOK && response.StatusCode != http.StatusNoContent {
		content, _ := io.ReadAll(response.Body)
		return fmt.Errorf("upload returned %d: %s", response.StatusCode, string(content))
	}
	return nil
}

func (client DatabricksHTTPClient) runSQL(ctx context.Context, warehouseID, statement string) error {
	body, err := json.Marshal(map[string]any{
		"warehouse_id": warehouseID, "statement": statement, "wait_timeout": "50s",
	})
	if err != nil {
		return fmt.Errorf("encode SQL request: %w", err)
	}
	response, err := client.post(ctx, client.Host+"/api/2.0/sql/statements", body)
	if err != nil {
		return err
	}
	var parsed struct {
		Status struct {
			State string `json:"state"`
		} `json:"status"`
	}
	if err := json.Unmarshal(response, &parsed); err != nil {
		return fmt.Errorf("SQL response did not parse: %w", err)
	}
	if parsed.Status.State != "SUCCEEDED" && parsed.Status.State != "" {
		return fmt.Errorf("SQL statement ended in state %q", parsed.Status.State)
	}
	return nil
}

func (client DatabricksHTTPClient) ensureVectorIndex(ctx context.Context, indexName, sourceTable, embeddingEndpoint string) error {
	body, err := json.Marshal(map[string]any{
		"name":          indexName,
		"endpoint_name": endpointFromIndexName(indexName),
		"primary_key":   "id",
		"index_type":    "DELTA_SYNC",
		"delta_sync_index_spec": map[string]any{
			"source_table":  sourceTable,
			"pipeline_type": "TRIGGERED",
			"embedding_source_columns": []map[string]string{
				{"name": "content", "embedding_model_endpoint_name": embeddingEndpoint},
			},
		},
	})
	if err != nil {
		return fmt.Errorf("encode index request: %w", err)
	}
	_, err = client.post(ctx, client.Host+"/api/2.0/vector-search/indexes", body)
	if err == nil {
		return nil
	}
	// Already exists (or a transient create failure): fall back to an
	// explicit sync of the existing index rather than treating it as fatal.
	if _, syncErr := client.post(ctx, client.Host+"/api/2.0/vector-search/indexes/"+indexName+"/sync", []byte(`{}`)); syncErr != nil {
		return fmt.Errorf("create index: %w; sync existing index: %v", err, syncErr)
	}
	return nil
}

// endpointFromIndexName lets DATABRICKS_VECTOR_SEARCH_INDEX carry an optional
// "endpoint|index" form; a bare name uses "fidelity-corroboration", the
// endpoint BUILDATHON.md provisioned.
func endpointFromIndexName(indexName string) string {
	if endpoint, _, found := strings.Cut(indexName, "|"); found {
		return endpoint
	}
	if env := os.Getenv("DATABRICKS_VECTOR_SEARCH_ENDPOINT"); env != "" {
		return env
	}
	return "fidelity-corroboration"
}

