package cli

import (
	"context"
	"encoding/json"
	"fmt"
	"path/filepath"
	"strings"

	"github.com/entireio/entire-graph/internal/fidelity"
	"github.com/entireio/entire-graph/internal/termsafe"
)

// fidelity-index is the offline prep step for corroboration (§12.2 Phase 1,
// build map #51): it extracts the repo's own commit messages, source
// comments/docstrings, and Markdown into fidelity-out/corpus.jsonl. That
// file is queried directly by verify-intent's local BM25 fallback, and — with
// --push and the Unity Catalog environment set — uploaded into a Delta table
// and DELTA_SYNC Vector Search index for the hosted path.
type fidelityIndexFlags struct {
	Repo            string
	OutputDirectory string
	Push            bool
}

type fidelityIndexResponse struct {
	FormatVersion int                    `json:"format_version"`
	Status        string                 `json:"status"`
	Repo          string                 `json:"repo"`
	Summary       fidelity.CorpusSummary `json:"summary"`
	IndexName     string                 `json:"index_name,omitempty"`
	Message       string                 `json:"message"`
}

func parseFidelityIndexFlags(args []string) (fidelityIndexFlags, error) {
	flags := fidelityIndexFlags{OutputDirectory: "fidelity-out"}
	for index := 0; index < len(args); index++ {
		argument := args[index]
		value := func() (string, error) {
			index++
			if index >= len(args) {
				return "", fmt.Errorf("%s requires a value", argument)
			}
			return args[index], nil
		}
		var err error
		switch argument {
		case "--repo":
			flags.Repo, err = value()
		case "--out":
			flags.OutputDirectory, err = value()
		case "--push":
			flags.Push = true
		default:
			if strings.HasPrefix(argument, "-") {
				return flags, fmt.Errorf("fidelity-index received unexpected argument %q", argument)
			}
			return flags, fmt.Errorf("fidelity-index takes no positional arguments, got %q", argument)
		}
		if err != nil {
			return flags, err
		}
	}
	return flags, nil
}

func runFidelityIndex(ctx context.Context, opts Options, args []string) error {
	flags, err := parseFidelityIndexFlags(args)
	if err != nil {
		return err
	}
	repo, err := resolveRepo(ctx, opts.Env, flags.Repo)
	if err != nil {
		return err
	}

	docs, err := fidelity.BuildCorpus(ctx, repo)
	if err != nil {
		return err
	}

	outputDirectory := flags.OutputDirectory
	if !filepath.IsAbs(outputDirectory) {
		outputDirectory = filepath.Join(repo, outputDirectory)
	}
	corpusPath := filepath.Join(outputDirectory, "corpus.jsonl")
	if err := fidelity.WriteCorpusJSONL(corpusPath, docs); err != nil {
		return err
	}
	summary := fidelity.SummarizeCorpus(docs, corpusPath)

	indexName := ""
	message := fmt.Sprintf("wrote %d corpus documents to %s; verify-intent will use its local BM25 index for corroboration", summary.Documents, corpusPath)
	if flags.Push {
		client, err := fidelity.NewDatabricksHTTPClientFromEnv(
			"", firstNonEmpty(opts.Env, "DATABRICKS_VECTOR_SEARCH_INDEX"))
		if err != nil {
			return fmt.Errorf("--push: %w", err)
		}
		indexName, err = client.SyncCorpus(ctx, docs)
		if err != nil {
			return fmt.Errorf("--push: %w", err)
		}
		summary.Pushed = true
		summary.PushDetail = "synced to " + indexName
		message = fmt.Sprintf("wrote %d corpus documents to %s and synced Databricks index %s", summary.Documents, corpusPath, indexName)
	}

	fmt.Fprintln(opts.Stderr, message)
	response := fidelityIndexResponse{
		FormatVersion: 1, Status: "ok", Repo: repo,
		Summary: summary, IndexName: indexName, Message: message,
	}
	encoder := json.NewEncoder(termsafe.NewJSONWriter(opts.Stdout))
	encoder.SetEscapeHTML(false)
	return encoder.Encode(response)
}

// firstNonEmpty resolves the vector-search index name from the process
// environment; kept tiny and local since fidelity-index is the only caller.
func firstNonEmpty(env EntireEnv, key string) string {
	_ = env
	return envLookup(key)
}

