package fidelity

import (
	"os"
	"path/filepath"
	"testing"
)

func TestBuildCorpusExtractsCommitsCommentsAndMarkdown(t *testing.T) {
	repo := t.TempDir()
	runGit(t, repo, "init")
	runGit(t, repo, "config", "user.email", "fidelity@example.test")
	runGit(t, repo, "config", "user.name", "Fidelity Test")

	write := func(name, content string) {
		if err := os.WriteFile(filepath.Join(repo, name), []byte(content), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	write("dispatch.go", "package dispatch\n\n"+
		"// RouteRequest sends the incoming payload to the handler registered\n"+
		"// for its message type, falling back to the dead-letter queue.\n"+
		"func RouteRequest() {}\n"+
		"\n//nolint:gocyclo\nfunc noisy() {}\n")
	write("README.md", "# Billing service\n\nThe billing service reconciles invoices against the ledger nightly.\n")
	runGit(t, repo, "add", ".")
	runGit(t, repo, "commit", "-m", "feat(dispatch): route requests through the typed handler registry")

	docs, err := BuildCorpus(t.Context(), repo)
	if err != nil {
		t.Fatal(err)
	}

	kinds := map[string]int{}
	var commentDoc, docDoc, commitDoc *CorpusDoc
	for i := range docs {
		kinds[docs[i].Kind]++
		switch {
		case docs[i].Kind == "comment" && commentDoc == nil:
			commentDoc = &docs[i]
		case docs[i].Kind == "doc":
			docDoc = &docs[i]
		case docs[i].Kind == "commit":
			commitDoc = &docs[i]
		}
	}
	if kinds["comment"] == 0 || kinds["doc"] == 0 || kinds["commit"] == 0 {
		t.Fatalf("expected all three kinds, got %#v", kinds)
	}
	if commentDoc == nil || !contains(commentDoc.Content, "dead-letter queue") {
		t.Fatalf("comment doc missing or wrong: %#v", commentDoc)
	}
	// The block-grouping means the two-line doc comment is ONE document.
	if commentDoc.Path != "dispatch.go" {
		t.Fatalf("comment doc path = %q", commentDoc.Path)
	}
	if docDoc == nil || !contains(docDoc.Content, "reconciles invoices") {
		t.Fatalf("markdown doc missing or wrong: %#v", docDoc)
	}
	if commitDoc == nil || !contains(commitDoc.Content, "typed handler registry") {
		t.Fatalf("commit doc missing or wrong: %#v", commitDoc)
	}
	// The //nolint directive line must not survive as its own document.
	for _, doc := range docs {
		if contains(doc.Content, "nolint") {
			t.Fatalf("directive noise leaked into corpus: %#v", doc)
		}
	}
}

func TestLocalIndexCorroboratesOnlyRealMatches(t *testing.T) {
	docs := []CorpusDoc{
		{ID: "commit:a1", Kind: "commit", Content: "feat(auth): validate the session token against the revocation list before issuing a refresh"},
		{ID: "billing.go:12", Kind: "comment", Path: "billing.go", Content: "reconcile invoices against the ledger and emit a discrepancy event"},
		{ID: "README.md:1", Kind: "doc", Path: "README.md", Content: "the scheduler runs every cron tick and drains the work queue"},
	}
	index := NewLocalIndex(docs)

	verified, snippet, err := index.Corroborate(t.Context(), "does auth check the session token against a revocation list")
	if err != nil {
		t.Fatal(err)
	}
	if !verified || !contains(snippet, "revocation list") {
		t.Fatalf("expected a corroborating hit, got verified=%v snippet=%q", verified, snippet)
	}

	verified, _, err = index.Corroborate(t.Context(), "kubernetes pod autoscaling thresholds for the ingress controller")
	if err != nil {
		t.Fatal(err)
	}
	if verified {
		t.Fatal("unrelated hypothesis must not be corroborated")
	}
}

func TestLocalIndexScoreEdgeFailsClosed(t *testing.T) {
	index := NewLocalIndex(nil)
	if _, err := index.ScoreEdge(t.Context(), "X calls Y", nil); err == nil {
		t.Fatal("local index must not pretend to score edges")
	}
	verified, _, err := index.Corroborate(t.Context(), "anything")
	if err != nil || verified {
		t.Fatalf("empty index Corroborate = %v, %v; want false, nil", verified, err)
	}
}

func TestCorpusJSONLRoundTrip(t *testing.T) {
	path := filepath.Join(t.TempDir(), "nested", "corpus.jsonl")
	want := []CorpusDoc{
		{ID: "commit:a1", Kind: "commit", Content: "one"},
		{ID: "x.go:3", Kind: "comment", Path: "x.go", Content: "two"},
	}
	if err := WriteCorpusJSONL(path, want); err != nil {
		t.Fatal(err)
	}
	got, err := LoadCorpusJSONL(path)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) != len(want) || got[0] != want[0] || got[1] != want[1] {
		t.Fatalf("round trip = %#v, want %#v", got, want)
	}
}

func contains(haystack, needle string) bool {
	return len(haystack) >= len(needle) && (haystack == needle || indexOf(haystack, needle) >= 0)
}

func indexOf(haystack, needle string) int {
	for i := 0; i+len(needle) <= len(haystack); i++ {
		if haystack[i:i+len(needle)] == needle {
			return i
		}
	}
	return -1
}

