func TestFidelityIndexWritesCorpusArtifact(t *testing.T) {
	repo := t.TempDir()
	write(t, repo, "handler.go", "package handler\n\n"+
		"// DispatchByType looks the handler up in the registry by the payload's\n"+
		"// declared message type and invokes it with the decoded body.\n"+
		"func DispatchByType() {}\n")
	write(t, repo, "docs/overview.md", "# Overview\n\nThe gateway authenticates every request before routing it downstream.\n")

	var out, errOut bytes.Buffer
	err := runFidelityIndex(t.Context(), Options{Env: EntireEnv{RepoRoot: repo}, Stdout: &out, Stderr: &errOut}, nil)
	if err != nil {
		t.Fatal(err)
	}
	var response fidelityIndexResponse
	if err := json.Unmarshal(out.Bytes(), &response); err != nil {
		t.Fatalf("stdout was not clean JSON: %v\n%s", err, out.String())
	}
	if response.Status != "ok" || response.Summary.Documents < 2 {
		t.Fatalf("response = %#v, want >=2 documents", response)
	}
	if response.Summary.ByKind["comment"] == 0 || response.Summary.ByKind["doc"] == 0 {
		t.Fatalf("expected comment and doc kinds: %#v", response.Summary.ByKind)
	}
	corpusPath := filepath.Join(repo, "fidelity-out", "corpus.jsonl")
	if _, err := os.Stat(corpusPath); err != nil {
		t.Fatalf("corpus.jsonl was not written: %v", err)
	}
}

