// unreachableAdapter yields one changed entity with no matching intent and
// no graph symbol, so it lands in unverifiable_coverage — the tier the
// local-corpus corroboration path (§12.15) enhances.
type unreachableAdapter struct{}

func (unreachableAdapter) CheckpointTranscript(context.Context, string) (string, error) {
	return "Implement the payment retry policy.", nil
}
func (unreachableAdapter) CheckpointCommit(_ context.Context, checkpoint string) (string, error) {
	if checkpoint == "checkpoint-0" {
		return "base", nil
	}
	return "head", nil
}
func (unreachableAdapter) Graph(context.Context) (fidelity.GraphSnapshot, error) {
	return fidelity.GraphSnapshot{Symbols: []fidelity.Symbol{{QualifiedName: "app.PaymentRetryPolicy"}}}, nil
}
func (unreachableAdapter) ChangedEntities(context.Context, string, string) ([]fidelity.ChangedEntity, error) {
	return []fidelity.ChangedEntity{{Name: "reticulateSplines", FilePath: "internal/geometry/spline.go", StartLine: 9}}, nil
}

func TestVerifyIntentCorroboratesUnverifiableCoverageFromLocalCorpus(t *testing.T) {
	t.Setenv("DATABRICKS_HOST", "")
	t.Setenv("DATABRICKS_TOKEN", "")
	repo := t.TempDir()
	config := strings.Replace(verifyIntentConfig,
		"databricks:\n  calibration_enabled: false",
		"databricks:\n  calibration_enabled: false\n  coverage_corroboration_enabled: true", 1)
	if err := os.WriteFile(filepath.Join(repo, "fidelity.config.yaml"), []byte(config), 0o600); err != nil {
		t.Fatal(err)
	}
	corpus := []fidelity.CorpusDoc{
		{ID: "internal/geometry/spline.go:9", Kind: "comment", Path: "internal/geometry/spline.go",
			Content: "reticulateSplines resamples the control polygon so the spline interpolation stays numerically stable near sharp corners"},
		{ID: "commit:zzz", Kind: "commit", Content: "unrelated: bump the linter version"},
	}
	if err := fidelity.WriteCorpusJSONL(filepath.Join(repo, "fidelity-out", "corpus.jsonl"), corpus); err != nil {
		t.Fatal(err)
	}

	var out, errOut bytes.Buffer
	err := runVerifyIntentWithAdapter(t.Context(), Options{Env: EntireEnv{RepoRoot: repo}, Stdout: &out, Stderr: &errOut}, []string{"checkpoint-1", "--base", "checkpoint-0"}, unreachableAdapter{})
	if err != nil {
		t.Fatal(err)
	}
	var response verifyIntentResponse
	if err := json.Unmarshal(out.Bytes(), &response); err != nil {
		t.Fatalf("stdout was not clean JSON: %v\n%s", err, out.String())
	}
	entries := response.Verification.Reconciliation.UnverifiableCoverage
	if len(entries) == 0 {
		t.Fatalf("expected an unverifiable_coverage entry to corroborate: %#v", response.Verification.Reconciliation)
	}
	entry := entries[0]
	if !entry.Corroboration.Attempted {
		t.Fatalf("corroboration was not attempted against the local corpus: %#v", entry)
	}
	if entry.Corroboration.Verified == nil || !*entry.Corroboration.Verified {
		t.Fatalf("local corpus has a matching doc but corroboration.verified = %#v", entry.Corroboration.Verified)
	}
	if entry.VerificationPath != "manual_review_recommended" {
		t.Fatalf("baseline verification_path must survive corroboration: %q", entry.VerificationPath)
	}
}

